import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            return hasNextByte() ? buffer[ptr++] : -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ' && c != -1) {
                c = readByte();
            }
            if (c == -1) return -1;
            int res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = readByte();
            }
            return res;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n == -1) return;
        int k = scanner.nextInt();
        int t = scanner.nextInt();

        int[] p = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            p[i] = scanner.nextInt();
        }

        int[] a = new int[k + 1];
        int count = 0;
        for (int i = 1; i <= n; i++) {
            int g = scanner.nextInt();
            if (g == 1) {
                count++;
                a[count] = i;
            }
        }

        int maxScore = 9 * k;
        final int INF = 1_000_000_000;

        int[][] dp = new int[k + 1][maxScore + 1];
        for (int j = 0; j <= k; j++) {
            Arrays.fill(dp[j], INF);
        }
        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            int pi = p[i];
            int maxJ = Math.min(i, k);
            for (int j = maxJ; j >= 1; j--) {
                int cost = Math.abs(a[j] - i);
                int[] prevRow = dp[j - 1];
                int[] currRow = dp[j];
                int maxS = 9 * j;
                for (int s = pi; s <= maxS; s++) {
                    int prevCost = prevRow[s - pi];
                    if (prevCost != INF) {
                        int candidate = prevCost + cost;
                        if (candidate < currRow[s]) {
                            currRow[s] = candidate;
                        }
                    }
                }
            }
        }

        int ans = 0;
        for (int s = maxScore; s >= 0; s--) {
            if (dp[k][s] <= t) {
                ans = s;
                break;
            }
        }

        System.out.println(ans);
    }
}
